def esc(v): return html.escape(str(v))
def now(): return datetime.now(KST).isoformat()
def key(): return uuid.uuid4().hex
def card(title, text=''):
    st.markdown(f'<div class="card"><b>{esc(title)}</b><div style="white-space:pre-wrap">{esc(text)}</div></div>',unsafe_allow_html=True)

def digest(s): return hmac.new(st.secrets['AUTH_SECRET'].encode(),s.encode(),hashlib.sha256).hexdigest()
def password_hash(p):
    salt=secrets.token_hex(16)
    return salt+':'+hashlib.pbkdf2_hmac('sha256',p.encode(),bytes.fromhex(salt),310000).hex()
def verify(p, stored):
    salt, hashed=stored.split(':')
    return hmac.compare_digest(hashed,hashlib.pbkdf2_hmac('sha256',p.encode(),bytes.fromhex(salt),310000).hex())
@st.cache_resource
def connection_pool():
    return ConnectionPool(st.secrets['DATABASE_URL'],min_size=1,max_size=5,
        kwargs={'prepare_threshold':None,'connect_timeout':10},timeout=12)
def db(): return connection_pool().connection()


@st.cache_resource
def setup():
    with db() as c:
        c.execute('''CREATE TABLE IF NOT EXISTS public.lumora_families(id text primary key,name text not null,invite text unique not null,data jsonb not null default '{}'::jsonb);
CREATE TABLE IF NOT EXISTS public.lumora_users(id text primary key,family text not null references public.lumora_families(id),username text unique not null,password text not null,name text not null,role text not null,blood text not null);
CREATE TABLE IF NOT EXISTS public.lumora_sessions(token text primary key,userid text not null references public.lumora_users(id),expires timestamptz not null);
CREATE TABLE IF NOT EXISTS public.lumora_attempts(username text primary key,count integer not null default 0,last_at timestamptz not null);
ALTER TABLE public.lumora_families ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.lumora_users ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.lumora_sessions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.lumora_attempts ENABLE ROW LEVEL SECURITY;''')
    return True

def session_user(token):
    if not token: return None
    with db() as c:
        row=c.execute('SELECT u.id,u.family,u.username,u.name,u.role,u.blood FROM public.lumora_sessions s JOIN public.lumora_users u ON u.id=s.userid WHERE s.token=%s AND s.expires>now()',(digest(token),)).fetchone()
    return dict(zip(['id','family','username','name','role','blood'],row)) if row else None

def screen_user(token):
    cached=st.session_state.get('_screen_auth')
    if token and cached and cached['token']==token and time.monotonic()-cached['at']<30:
        return cached['user']
    result=session_user(token)
    st.session_state['_screen_auth']={'token':token,'at':time.monotonic(),'user':result}
    return result

def read_family_data(user):
    with db() as c:
        row=c.execute("""SELECT f.name,f.data,
            COALESCE((SELECT jsonb_agg(jsonb_build_object('id',m.id,'name',m.name,'role',m.role,'blood',m.blood) ORDER BY m.id)
            FROM public.lumora_users m WHERE m.family=f.id),'[]'::jsonb)
            FROM public.lumora_families f JOIN public.lumora_users u ON u.family=f.id
            WHERE u.id=%s AND f.id=%s""",(user['id'],user['family'])).fetchone()
    if not row:raise ValueError('가족 정보를 확인할 수 없습니다.')
    return row[0],row[1],row[2]

def family_data(user):
    cached=st.session_state.get('_family_snapshot')
    if cached and cached['uid']==user['id'] and time.monotonic()-cached['at']<30:
        return cached['value']
    value=read_family_data(user)
    st.session_state['_family_snapshot']={'uid':user['id'],'at':time.monotonic(),'value':value}
    return value

def navigate(label):
    st.session_state['page']=label

def refresh_family():
    st.session_state.pop('_family_snapshot',None)


# Every mutation authenticates server-side and locks the family row. Never accept a client-supplied family ID.
def mutate(fn):
    user=session_user(st.session_state.get('token'))
    if not user: st.error('로그인이 만료되었습니다. 다시 로그인해 주세요.'); st.stop()
    with db() as c:
        row=c.execute('SELECT data FROM public.lumora_families WHERE id=%s FOR UPDATE',(user['family'],)).fetchone()
        data=row[0]
        fn(data,user)
        c.execute('UPDATE public.lumora_families SET data=%s WHERE id=%s',(Jsonb(data),user['family']))
    # Reuse the committed record instead of downloading all photos and letters again.
    cached=st.session_state.get('_family_snapshot')
    if cached and cached['uid']==user['id']:
        family_name,_,members=cached['value']
        st.session_state['_family_snapshot']={'uid':user['id'],'at':time.monotonic(),
            'value':(family_name,data,members)}
    else:
        refresh_family()

def award(data,user,activity,points):
    # One reward per activity per member per KST day; edits/deletions never reset ledger.
    ledger=data.setdefault('ledger',{})
    stamp=f'{TODAY}:{user["id"]}:{activity}'
    if stamp not in ledger:
        before=sum(ledger.values()); ledger[stamp]=points
        if stage(before)!=stage(before+points): st.session_state['celebrate']=True

def stage(p): return 0 if p<60 else 1 if p<300 else 2 if p<1200 else 3

def save_item(collection, payload, reward=None, itemid=None):
    ident=itemid or key()
    def action(data,user):
        items=data.setdefault(collection,{})
        old=items.get(ident)
        if old and old['author']!=user['id']: raise ValueError('작성자만 수정할 수 있습니다.')
        items[ident]={**payload,'author':user['id'],'name':user['name'],'created':old['created'] if old else now()}
        if reward: award(data,user,*reward)
    mutate(action)
    if collection=='letters':st.session_state['_reset_letter_draft']=True
    messages={'notes':'메모를 남겼습니다.','letters':'편지를 봉인했습니다.','buckets':'가족 목표를 추가했습니다.','events':'일정을 저장했습니다.','memories':'추억을 저장했습니다.'}
    messages.update({'moods':'오늘의 기분을 기록했어요.','answers':'오늘의 질문에 답변을 남겼어요.'})
    st.session_state['_save_notice']=messages.get(collection,'저장했습니다.') if collection in ('moods','answers') or not itemid else '수정했습니다.'
    st.rerun()

def delete_item(collection,ident):
    def action(data,user):
        item=data.get(collection,{}).get(ident)
        if not item or item['author']!=user['id']: raise ValueError('작성자만 삭제할 수 있습니다.')
        del data[collection][ident]
    mutate(action);st.rerun()

def app_share_url():
    raw=st.secrets.get('APP_URL','').strip()
    parsed=urlsplit(raw)
    host=(parsed.hostname or '').lower()
    if parsed.scheme!='https' or not host or parsed.username or parsed.password or any(x in host for x in ['your-app','yourapp','our-app','example','localhost']):
        return None
    return urlunsplit((parsed.scheme,parsed.netloc,parsed.path.rstrip('/'),'',''))

