def can_read_letter(letter,viewer):
    return (letter['author']==viewer['id'] or letter.get('visibility')=='가족'
            or viewer['id'] in letter.get('recipients',[]))

def letter_paper(letter,preview=False):
    content=letter.get('text','')
    if preview and len(content)>150:content=content[:150]+'…'
    pad='16px' if preview else '32px'
    size='14px' if preview else '18px'
    return ('<article style="position:relative;background:#fffdf6;'
        'border:1px solid #e6dfcc;border-radius:3px 3px 14px 3px;'
        'box-shadow:3px 5px 0 #ece9dd,0 12px 28px #5f573414;'
        'padding:'+pad+';min-height:'+('190px' if preview else '380px')+';'
        'color:#4b5146;overflow-wrap:anywhere;">'
        '<div style="display:flex;justify-content:space-between;align-items:center;'
        'border-bottom:1px solid #cec8ae;padding-bottom:12px;margin-bottom:18px;'
        'font-size:10px;letter-spacing:2px;color:#8a967a">'
        '<span>LUMORA</span><span>✦</span></div>'
        '<div style="font-size:'+('17px' if preview else '24px')+';font-weight:600;'
        'color:#53664b;margin:0 0 18px;line-height:1.5">'+esc(letter['title'])+'</div>'
        '<div style="white-space:pre-wrap;font-size:'+size+';line-height:32px;'
        'min-height:128px;background-image:repeating-linear-gradient(to bottom,'
        'transparent 0px,transparent 30px,#e5e2d3 31px,transparent 32px);">'+esc(content)+'</div>'
        '<div style="text-align:right;font-size:12px;color:#8a8c7c;margin-top:22px;'
        'padding-top:10px">From. '+esc(letter.get('name',''))+'</div></article>')

@st.dialog('편지 보관함',width='large')
def open_letter_archive():
    selected=st.session_state.get('_reading_letter')
    reading=data.get('letters',{}).get(selected)
    if reading and reading['unlock']<=str(TODAY) and (can_read_letter(reading,user)):
        if st.button('닫기',icon=':material/close:',key='close_reading_letter'):
            st.session_state.pop('_reading_letter',None)
            st.rerun(scope='fragment')
        st.caption(reading['name']+' · '+reading['unlock'])
        st.markdown(letter_paper(reading),unsafe_allow_html=True)
        return
    mine,family_tab=st.tabs(['나의 편지','가족이 공유한 편지'])
    for tab,is_mine in [(mine,True),(family_tab,False)]:
        with tab:
            visible=[(i,l) for i,l in data.get('letters',{}).items() if (l['author']==user['id'] if is_mine else l['author']!=user['id'] and can_read_letter(l,user))]
            if not visible:st.caption('보관된 편지가 없어요.')
            with st.container(key='lettergrid'+str(is_mine)):
                cols=st.columns(3)
                for n,(ident,l) in enumerate(sorted(visible,key=lambda pair:pair[1]['unlock'])):
                    with cols[n%3]:
                        with st.container(border=True):
                            if l['unlock']<=str(TODAY):
                                st.markdown(letter_paper(l,preview=True),unsafe_allow_html=True)
                                st.caption(l['name']+' · '+l['unlock']+' · 봉인 해제')
                                if st.button('확대해서 읽기',key='read_'+ident,use_container_width=True):
                                    st.session_state['_reading_letter']=ident
                                    st.rerun(scope='fragment')
                            else:
                                st.image(envelope_image(),use_container_width=True)
                                st.markdown('**'+esc(l['title'])+'**')
                                st.caption(l['name']+' · '+l['unlock']+' · 봉인 중')
                            if l['author']==user['id'] and st.button('삭제',key='ld'+ident):delete_item('letters',ident)

@st.dialog('알림',width='large')
def open_notifications():
    alerts=[]
    for l in data.get('letters',{}).values():
        if l['unlock']<=str(TODAY) and can_read_letter(l,user):
            alerts.append((l['unlock'],'✉️ 편지를 열어볼 수 있어요',l['title'],l['name']))
    for collection,label,field in [('notes','💬 가족 메모가 도착했어요','text'),('memories','📷 새로운 추억을 남겼어요','title'),('answers','💡 오늘의 질문에 답했어요','text'),('moods','🌿 가족의 기분이 도착했어요','mood')]:
        for item in data.get(collection,{}).values():
            if item.get('author')!=user['id']:
                alerts.append((item.get('created',''),label,item.get(field,''),item.get('name','가족')))
    for item in data.get('events',{}).values():
        when=item.get('date','')
        if str(TODAY)<=when<=str(TODAY+timedelta(days=7)):
            alerts.append((when,'📅 다가오는 가족 일정',item.get('title',''),when+' · '+item.get('name','가족')))
        elif item.get('author')!=user['id']:
            alerts.append((item.get('created',''),'📅 가족 일정이 등록됐어요',item.get('title',''),item.get('name','가족')))
    for item in data.get('buckets',{}).values():
        if item.get('done'):
            alerts.append((item.get('done_date',''),'🎉 가족 목표를 이뤘어요',item.get('title',''),item.get('done_date','')))
        elif item.get('author')!=user['id']:
            alerts.append((item.get('created',''),'🌱 새로운 가족 목표',item.get('title',''),item.get('name','가족')))
    if not alerts:st.caption('아직 새로운 소식이 없어요.')
    for when,title,body,by in sorted(alerts,key=lambda item:item[0],reverse=True)[:50]:
        with st.container(border=True):
            st.markdown('**'+title+'**')
            st.write(body)
            st.caption(by)
    st.caption('최근 소식 최대 50개를 모아 보여줍니다. 앱 내부 알림이며 푸시·읽음 관리는 제공하지 않습니다.')


