@st.cache_data(show_spinner=False)
def character(index,level):
    if level<2:
        im=Image.new('RGB',(480,440),'#faf7ef'); d=ImageDraw.Draw(im)
        d.ellipse((120,65,360,390),fill='#eee6cd',outline='#bcae86',width=5)
        for x,y in [(170,150),(270,220),(190,295)]: d.ellipse((x,y,x+35,y+25),fill='#ccd7bf')
        if level==1:
            d.line([(130,220),(180,190),(225,235),(270,195),(350,220)],fill='#8d8065',width=9)
            d.ellipse((190,205,205,222),fill='#3e493f');d.ellipse((265,205,280,222),fill='#3e493f')
    else:
        sheet=Image.open(io.BytesIO(base64.b64decode(ART)))
        group,col=divmod(index,5);row=group*2+(1 if level==3 else 0)
        w,h=sheet.size
        im=sheet.crop((round(col*w/5),round(row*h/6),round((col+1)*w/5),round((row+1)*h/6)))
    out=io.BytesIO(); im.convert('RGB').save(out,format='WEBP',quality=82,method=3);return out.getvalue()

